package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalSignedUnitRounds.*;
import org.kanger.ContextUniversalSignedUnitRounds.Result;
import org.kanger.ContextUniversalSignedUnitExchange.Exchange;
import org.kanger.ContextWitnessResultTransport.*;

/** Universal heads must cross a full immutable all-cut barrier before use by peers. */
public final class ContextUniversalSymbolicHeadRoundsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalFrozenBranch.Limits limits(int fact){return ContextUniversalSignedFixedApplicationRoundsRunner.limits(fact);}
    static Result run(Snapshot x,List<Snapshot> a,Packet p,Map<Cut,PrivatePool> pools,Exchange e,int fact,int rounds){return ContextUniversalSignedUnitRounds.runSymbolicHeads(x,a,p,pools,e,limits(fact),rounds,WORK);}
    static Result stable(Result r,Exchange e){ContextUniversalSignedFixedApplicationRoundsRunner.stable(r,e);for(Round n:r.history)for(ContextUniversalFrozenConstraints.Result c:n.checks.values())require(c.symbolicHeads,"explicit mode in every cut and round");return r;}
    static void incomplete(Result r,String phase,int completed){ContextUniversalSignedFixedApplicationRoundsRunner.incomplete(r,phase,completed,"atomic refusal");++checks;}
    static void baseline()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,"!@x @y p(x)&&q(x)->~r(y);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> list=Collections.singletonList(a);
        incomplete(ContextUniversalSignedUnitRounds.runFixedApplications(x,list,p,Collections.emptyMap(),null,limits(1),8,WORK),"symbolic-collection",0);
        Result r=stable(run(x,list,p,Collections.emptyMap(),null,1,8),null);require(r.completedRounds==2&&!r.history.get(0).commonChanged&&!r.history.get(0).privateChanged&&r.history.get(0).symbolicChanged,"symbolic-only growth forces next all-cut pass");
        require(r.output.packet.items.size()==p.items.size()&&r.symbolicOutput.units.size()==1,"universal not sampled into fixed packet");require(r.symbolicOutput.units.get(0).support.depth==1&&r.symbolicOutput.units.get(0).support.sources.size()==3,"universal1 exact three Sources");
        require(stable(run(x,list,r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput).completedRounds==1,"actual continuation stable1");
        incomplete(run(x,list,p,Collections.emptyMap(),null,1,1),"round-limit",1);incomplete(run(x,list,p,Collections.emptyMap(),null,0,8),"symbolic-collection",0);
        Result old=ContextUniversalSignedUnitRounds.runFixedApplications(x,list,p,Collections.emptyMap(),null,limits(16),8,WORK);require(old.status==Status.STABLE_UNIT_POOLS&&old.symbolicOutput.units.get(0).support.depth==2,"old entry retains binary symbolic2");Result improved=stable(run(x,list,old.output.packet,old.output.privatePools,old.symbolicOutput,16,8),old.symbolicOutput);require(improved.completedRounds==2&&!improved.history.get(0).commonChanged&&improved.history.get(0).symbolicChanged&&improved.symbolicOutput.units.get(0).support.depth==1&&old.symbolicOutput.units.get(0).support.depth==2,"grade-only symbolic change advances barrier, old frame immutable");
        Snapshot b=bind(false,"!r(987654);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Result no=run(x,order,p,Collections.emptyMap(),null,1,8);refuted(no,2,"previously unseen value next barrier");require(no.refutations.get(Cut.of(b)).proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"unseen empty2 exact Sources");require(hasRecipe(no.refutations.get(Cut.of(b)).proofs.get(0)),"flattened rejection retains symbolic-head recipe");}
        Snapshot bad=bind(false,"!bad(1)||other(1);");incomplete(run(x,Arrays.asList(a,bad),p,Collections.emptyMap(),null,1,8),"checks",0);
        incomplete(run(x,list,ContextPrivateWitnessPoolRunner.common(x),Collections.emptyMap(),r.symbolicOutput,16,8),"preflight",0);
        incomplete(ContextUniversalSignedUnitRounds.runSymbolicHeads(x,list,p,Collections.emptyMap(),null,limits(16),8,1),"preflight",0);
        Map<Cut,Packet> outputs=new LinkedHashMap<>();for(Map.Entry<Cut,ConstraintTransfer> e:r.output.branches.entrySet())outputs.put(e.getKey(),e.getValue().output);require(ContextWitnessResultTransport.family(r.history.get(1).input,new ArrayList<>(outputs.keySet()),WORK).finish(outputs,WORK).status==FamilyStatus.INCOMPLETE,"no STEP/admission authority");
    }
    static void refuted(Result r,int round,String why){require(r.status==Status.REFUTED&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&!r.refutations.isEmpty()&&r.completedRounds==round-1,why+": "+r.reason);Set<ContextUniversalFrozenConstraints.Proof> seen=Collections.newSetFromMap(new IdentityHashMap<ContextUniversalFrozenConstraints.Proof,Boolean>());for(Refutation f:r.refutations.values()){require(f.round==round&&!f.proofs.isEmpty(),"actual next-input rejection receipt");for(ContextUniversalFrozenConstraints.Proof p:f.proofs){require(p.clause==null,"only empty rejection roots");ContextUniversalSymbolicHeadApplicationsRunner.audit(p,seen);}}}
    static boolean hasRecipe(ContextUniversalFrozenConstraints.Proof p){if(p==null)return false;require(p.exchanged==null,"no imported owner in rejection DAG");if(p.symbolicHeadRecipe)return true;if(hasRecipe(p.unit)||hasRecipe(p.horn)||hasRecipe(p.producer))return true;for(ContextUniversalFrozenConstraints.Proof d:p.donors)if(hasRecipe(d))return true;return false;}
    static void chainAndScope()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,"!@x @y p(x)&&q(x)->~r(y);"),bridge=bind(false,"!@v ~r(v)->~s(v);"),opinion=bind(false,"!s(987654);");Packet p=ContextPrivateWitnessPoolRunner.common(x);
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,bridge,opinion),Arrays.asList(opinion,bridge,a))){Result no=run(x,order,p,Collections.emptyMap(),null,2,8);refuted(no,3,"two symbolic barriers before final opinion");require(no.refutations.get(Cut.of(opinion)).proofs.stream().anyMatch(v->v.support.depth==3&&v.support.sources.size()==5),"symbolic chain empty3 retains five Sources");}
        Snapshot anchor=bind(true,"!anchor(1);"),yes=bind(false,"!@v r(v);"),negative=bind(false,"!@v ~r(v);");Result independent=stable(run(anchor,Arrays.asList(yes,negative),ContextPrivateWitnessPoolRunner.common(anchor),Collections.emptyMap(),null,1,1),null);require(independent.symbolicOutput.units.isEmpty()&&independent.output.packet.items.size()==1,"independent contradictory opinions never communalized by unrelated anchor");
    }
    static void privateAndAlternatives()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@w @v p(w,1)&&q(w,1)->~r(w,v);"),a=bind(false,"!$w p(w,1)&&q(w,1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Map<Cut,PrivatePool> pools=Collections.singletonMap(pool.cut,pool);Result r=stable(run(x,Collections.singletonList(a),p,pools,null,1,8),null);require(r.symbolicOutput.units.size()==1&&r.symbolicOutput.units.get(0).clause.variables.size()==1&&r.symbolicOutput.units.get(0).clause.origins.size()==1&&r.symbolicOutput.units.get(0).support.depth==1&&r.symbolicOutput.units.get(0).support.sources.contains(a.primary.get(0).source),"mixed actual private Origin/universal head at1");require(r.output.packet.items.size()==1&&pool.common==p,"raw witnesses withheld, old private input immutable");require(stable(run(x,Collections.singletonList(a),r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput).completedRounds==1,"private symbolic continuation exact frame");
        Snapshot yes=bind(false,"!@w @v r(w,v);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,yes),Arrays.asList(yes,a))){Result no=run(x,order,p,pools,null,1,8);refuted(no,2,"mixed Origin head versus independent universal");require(no.refutations.get(Cut.of(yes)).proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==3&&v.support.sources.contains(a.primary.get(0).source)),"actual binding retained in refutation");}
        incomplete(run(x,Collections.singletonList(a),p,Collections.emptyMap(),null,1,8),"checks",0);
        Snapshot ax=bind(true,"!p(1); !q(1);"),donor=bind(false,"!@x @y p(x)&&q(x)->~r(y);"),loop=bind(false,"!@y r(y)->r(y);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(donor,loop),WORK);Packet ap=ContextPrivateWitnessPoolRunner.common(ax);Result alts=stable(run(ax,Collections.singletonList(group),ap,Collections.emptyMap(),null,2,8),null);require(alts.symbolicOutput.units.size()==2&&alts.symbolicOutput.units.stream().anyMatch(u->u.support.depth==1&&u.support.sources.size()==3)&&alts.symbolicOutput.units.stream().anyMatch(u->u.support.depth==2&&u.support.sources.size()==4),"Source superset kept alongside shorter subset");incomplete(run(ax,Collections.singletonList(group),ap,Collections.emptyMap(),null,1,8),"symbolic-collection",0);
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("symbolic-head-rounds-").toString());baseline();privateAndAlternatives();chainAndScope();System.out.println("CONTEXT_UNIVERSAL_SYMBOLIC_HEAD_ROUNDS_PASS checks="+(checks+ContextUniversalSignedFixedApplicationRoundsRunner.checks+ContextUniversalSymbolicHeadApplicationsRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
